import fs from 'node:fs';
import assert from 'node:assert/strict';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
const stage='F:/VisibleMedicine/staging/20261023-fda-shoulder-surfaces',atlas=stage+'/atlas';
const phase=process.argv[2];assert(['tests','conversion'].includes(phase));
const root=stage+'/'+phase;assert(!fs.existsSync(root));fs.mkdirSync(root);
const files=['scripts/inspect-abaqus-shoulder-source.mjs','scripts/abaqus-quadratic-boundary.mjs','scripts/abaqus-instance-transform.mjs','scripts/test-abaqus-shoulder-source.mjs','scripts/test-abaqus-quadratic-boundary.mjs','scripts/test-abaqus-instance-transform.mjs','scripts/convert-pinned-fda-shoulder.mjs'];
const hash=b=>createHash('sha256').update(b).digest('hex');
const source=files.map(path=>({path,sha256:hash(fs.readFileSync(atlas+'/'+path))}));
const args=phase==='tests'?['--test','--test-concurrency=1','--test-reporter=tap','scripts/test-abaqus-shoulder-source.mjs','scripts/test-abaqus-quadratic-boundary.mjs','scripts/test-abaqus-instance-transform.mjs']:['--max-old-space-size=1536','scripts/convert-pinned-fda-shoulder.mjs','F:/VisibleMedicine/staging/20261023-fda-shoulder-source/Male-Shoulder.inp',stage+'/quarantine-surfaces'];
const stdout=fs.openSync(root+'/stdout.log','wx'),stderr=fs.openSync(root+'/stderr.log','wx');
const startedAt=new Date().toISOString();
const result=spawnSync(process.execPath,args,{cwd:atlas,env:{...process.env,NODE_OPTIONS:'',RAYON_NUM_THREADS:'1',GOMAXPROCS:'2'},windowsHide:true,stdio:['ignore',stdout,stderr]});
fs.closeSync(stdout);fs.closeSync(stderr);
for(const row of source)assert.equal(hash(fs.readFileSync(atlas+'/'+row.path)),row.sha256,'Source changed during '+phase);
const terminal={phase,startedAt,finishedAt:new Date().toISOString(),command:[process.execPath,...args],cwd:atlas,source,exitCode:result.status,signal:result.signal,error:result.error?.message,stdoutSha256:hash(fs.readFileSync(root+'/stdout.log')),stderrSha256:hash(fs.readFileSync(root+'/stderr.log')),installed:false,previewChanged:false};
fs.writeFileSync(root+'/TERMINAL.json',JSON.stringify(terminal,null,2)+'\n',{flag:'wx'});
console.log(JSON.stringify({phase,exitCode:result.status,signal:result.signal,log:root,tail:fs.readFileSync(root+'/stdout.log','utf8').slice(-1700),stderr:fs.readFileSync(root+'/stderr.log','utf8').slice(-1200)}));
process.exitCode=result.status??1;
